// NutriScanner — Input Validator & MVP Primary Intake Guard
const body = $input.item.json.body || $input.item.json;
const binaryData = $input.item.binary || {};
const mode = body.mode || (Object.keys(binaryData).length > 0 ? 'photo' : 'text');

// MVP Technical Constraint: 1 primary label photo per analysis call for fast & reliable inference
// Product Roadmap Vision: Multi-photo package analysis (1-4 images) is deferred to future phase
const MVP_PHOTO_LIMIT = 1;

if (mode === 'photo') {
  const binaryKeys = Object.keys(binaryData);
  const imageCount = binaryKeys.length;

  if (imageCount === 0) {
    return [{
      json: {
        is_error: true,
        error: {
          code: 'INVALID_INPUT',
          message: 'Setidaknya satu foto label harus disediakan.',
          retryable: false
        }
      }
    }];
  }

  if (imageCount > MVP_PHOTO_LIMIT) {
    return [{
      json: {
        is_error: true,
        error: {
          code: 'TOO_MANY_IMAGES',
          message: `Pada fase MVP saat ini, analisis AI menerima 1 foto terbaik per sesi (misal tabel gizi atau komposisi). Ditemukan ${imageCount} foto.`,
          retryable: false
        }
      }
    }];
  }

  const k = binaryKeys[0];
  const file = binaryData[k];
  let b64 = file.data;
  if (b64 === 'filesystem-v2' || !b64 || b64.length < 50) {
    try {
      const buf = await this.helpers.getBinaryDataBuffer(0, k);
      b64 = buf.toString('base64');
    } catch (e) {
      console.error(`Error reading binary buffer for ${k}:`, e);
    }
  }

  return [{
    json: {
      mode: 'photo',
      image_count: 1,
      session_id: `nutri_${Date.now()}`,
      image_url: `data:${file.mimeType || 'image/jpeg'};base64,${b64}`,
      is_error: false
    }
  }];
} else if (mode === 'text') {
  const labelText = body.text || '';
  if (!labelText.trim()) {
    return [{
      json: {
        is_error: true,
        error: {
          code: 'INVALID_INPUT',
          message: 'Teks label tidak boleh kosong.',
          retryable: false
        }
      }
    }];
  }

  return [{
    json: {
      mode: 'text',
      text: labelText,
      session_id: `nutri_${Date.now()}`,
      is_error: false
    }
  }];
} else if (mode === 'manual') {
  let manualData = body.manual;
  if (typeof manualData === 'string') {
    try { manualData = JSON.parse(manualData); } catch (e) {}
  }
  return [{
    json: {
      mode: 'manual',
      manual: manualData || {},
      session_id: `nutri_${Date.now()}`,
      is_error: false
    }
  }];
}

return [{
  json: {
    is_error: true,
    error: {
      code: 'INVALID_INPUT',
      message: 'Mode input tidak dikenali (harus photo, text, atau manual).',
      retryable: false
    }
  }
}];

// Prepare Groq AI Payload for MVP Single-Image Extraction
const data = $input.item.json;
const mode = data.mode;

const promptInstruction = `Anda adalah asisten ekstraksi data fakta label kemasan makanan/minuman yang sangat teliti, netral, dan patuh pada prinsip 'Facts, not verdicts'.

TUGAS:
Ekstrak seluruh informasi yang terlihat pada label ke dalam format JSON tunggal sesuai skema.

ATURAN MUTLAK:
1. Ekstrak HANYA informasi yang terlihat atau terbaca secara eksplisit.
2. JANGAN PERNAH mengarang, menebak, atau menambahkan informasi yang tidak ada. Jika suatu nilai (misal gula, natrium, takaran saji) tidak tertera di label, kembalikan null.
3. JANGAN memberikan penilaian kesehatan, skor nutrisi, atau kata 'sehat' / 'tidak sehat'.
4. Jangan melakukan perhitungan aritmatika; salin angka dan unit persis sebagaimana tertulis di label.
5. Pisahkan deklarasi alergen eksplisit (misal 'Mengandung alergen: susu') dari sekadar penyebutan bahan di komposisi.
6. Catat daftar 'missing_information' jika ada elemen penting yang tidak ditemukan pada label.
7. Kembalikan HANYA objek JSON valid sesuai skema berikut tanpa teks pembuka atau penutup.

Schema:
{
  "identity": {
    "name": string | null,
    "brand": string | null,
    "category": string | null
  },
  "serving": {
    "size": number | null,
    "unit": string | null,
    "servings_per_container": number | null,
    "basis": "per_serving" | "per_100g" | "per_100ml" | "per_package" | null
  },
  "nutrition": {
    "energy": number | null,
    "energy_kj": number | null,
    "protein": number | null,
    "total_fat": number | null,
    "saturated_fat": number | null,
    "carbohydrate": number | null,
    "sugar": number | null,
    "sodium": number | null,
    "additional": []
  },
  "ingredients": {
    "raw_text": string | null,
    "items": [
      {
        "name": string,
        "role": string | null,
        "description": string | null
      }
    ]
  },
  "allergens": {
    "explicit_declaration": string | null,
    "items": []
  },
  "missing_information": string[],
  "conflicts": []
}`;

if (mode === 'photo') {
  return [{
    json: {
      session_id: data.session_id,
      mode: 'photo',
      groq_payload: {
        model: 'qwen/qwen3.6-27b',
        messages: [
          {
            role: 'user',
            content: [
              {
                type: 'text',
                text: `${promptInstruction}

Ekstrak data gizi dan komposisi dari foto label ini ke format JSON.`
              },
              {
                type: 'image_url',
                image_url: {
                  url: data.image_url
                }
              }
            ]
          }
        ],
        reasoning_effort: 'none',
        max_completion_tokens: 1500,
        temperature: 0.2
      }
    }
  }];
} else if (mode === 'text') {
  return [{
    json: {
      session_id: data.session_id,
      mode: 'text',
      groq_payload: {
        model: 'qwen/qwen3.6-27b',
        messages: [
          {
            role: 'user',
            content: `${promptInstruction}

Ekstrak data gizi dan komposisi dari teks label berikut ke format JSON:

${data.text}`
          }
        ],
        reasoning_effort: 'none',
        max_completion_tokens: 1500,
        temperature: 0.2
      }
    }
  }];
} else {
  return [{
    json: {
      session_id: data.session_id,
      mode: 'manual',
      extraction: data.manual
    }
  }];
}

// NutriScanner — Deterministic Calculation & Provenance Engine
const allItems = $input.all();
if (allItems.length === 0) {
  return [{ json: { error: { code: 'NO_DATA', message: 'Tidak ada data untuk diproses.' } } }];
}

const itemJson = allItems[0].json;
const sessionId = itemJson.session_id || `nutri_${Date.now()}`;
const mode = itemJson.mode || 'photo';
let rawExtraction = {};

if (itemJson.error) {
  return [{
    json: {
      error: {
        code: itemJson.error.code || 'AI_PROVIDER_ERROR',
        message: itemJson.error.message || 'Gagal memproses gambar pada penyedia AI.',
        retryable: true
      }
    }
  }];
}

if (mode === 'manual') {
  rawExtraction = itemJson.extraction || {};
} else {
  try {
    let content = itemJson.choices?.[0]?.message?.content || '{}';
    content = content.replace(/<think>[\s\S]*?<\/think>/gi, '').trim();
    const match = content.match(/\{[\s\S]*\}/);
    if (match) content = match[0];
    rawExtraction = JSON.parse(content);
  } catch (e) {
    return [{
      json: {
        error: {
          code: 'JSON_PARSE_ERROR',
          message: 'Format ekstraksi AI tidak valid.',
          retryable: true
        }
      }
    }];
  }
}

const identity = rawExtraction.identity || { name: null, brand: null, category: null };
const serving = rawExtraction.serving || { size: null, unit: null, servings_per_container: null, basis: null };
const nutrition = rawExtraction.nutrition || { energy: null, energy_kj: null, protein: null, total_fat: null, saturated_fat: null, carbohydrate: null, sugar: null, sodium: null, additional: [] };
const ingredients = rawExtraction.ingredients || { raw_text: null, items: [] };
const allergens = rawExtraction.allergens || { explicit_declaration: null, items: [] };
const missingInfo = Array.isArray(rawExtraction.missing_information) ? [...rawExtraction.missing_information] : [];
const conflicts = Array.isArray(rawExtraction.conflicts) ? [...rawExtraction.conflicts] : [];

// STEP 1: Energy Normalization (kJ -> kcal)
if (nutrition.energy === null && typeof nutrition.energy_kj === 'number') {
  nutrition.energy = Math.round(nutrition.energy_kj * 0.239006);
}

// STEP 2: Validate Prerequisite for Package Calculation
const servingsCount = (typeof serving.servings_per_container === 'number' && serving.servings_per_container > 0)
  ? serving.servings_per_container
  : null;

const canCalculatePackage = servingsCount !== null;
const calculatedPackage = {};
const standardNutrients = ['energy', 'protein', 'total_fat', 'saturated_fat', 'carbohydrate', 'sugar', 'sodium'];

// STEP 3: Deterministic Package Calculation
for (const nutrient of standardNutrients) {
  const val = nutrition[nutrient];
  if (typeof val === 'number' && canCalculatePackage) {
    calculatedPackage[nutrient] = Math.round((val * servingsCount) * 100) / 100;
  } else {
    calculatedPackage[nutrient] = null;
  }
}

// STEP 4: Missing Information Honesty
if (!canCalculatePackage) {
  missingInfo.push('Jumlah sajian per kemasan tidak tercantum pada label; kalkulasi total per kemasan ditiadakan.');
}
if (!ingredients.raw_text && (!ingredients.items || ingredients.items.length === 0)) {
  missingInfo.push('Daftar komposisi tidak terdeteksi pada foto/teks label.');
}
if (nutrition.sugar === null) {
  missingInfo.push('Kandungan gula tidak tertera pada tabel gizi.');
}
if (nutrition.sodium === null) {
  missingInfo.push('Kandungan natrium tidak tertera pada tabel gizi.');
}

const canonicalResult = {
  session_id: sessionId,
  status: 'review_required',
  source: mode === 'manual' ? 'user_provided' : 'ai_extracted',
  usage: itemJson.usage || null,
  extraction: {
    identity,
    serving,
    nutrition,
    calculated: {
      package: calculatedPackage,
      can_calculate_package: canCalculatePackage
    },
    ingredients,
    allergens,
    missing_information: Array.from(new Set(missingInfo)),
    conflicts
  }
};

return [{
  json: canonicalResult
}];
